arguments:
$ErrorActionPreference = 'Stop'
$taskName = 'Codex_Launch_Cinebench_AfterCert_20260904T1616'
$scriptPath = 'C:\Assets\AssetValidation\AssetValidation-20260904T103354\Launch-CinebenchInteractiveSmoke-20260904T1616.ps1'
$exePath = 'C:\Assets\Cinebench2026\Cinebench.exe'
